(()=>{const uploadUrl=@json(route('admin.documents.chunks'));const csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';const CHUNK_SIZE=524288;document.addEventListener('DOMContentLoaded',()=>{const input=document.querySelector('#upload-modal input[type="file"]');const form=input?.closest('form');if(!input||!form)return;const submit=form.querySelector('button.primary[type="submit"]');const progress=document.createElement('div');progress.style.cssText='display:none;margin-top:4px;padding:12px;border:1px solid rgba(104,204,235,.13);border-radius:12px;background:rgba(67,194,229,.05);font-size:12px;color:#86a5b4';progress.innerHTML='<div style="display:flex;justify-content:space-between"><span class="upload-status">Preparing upload…</span><strong class="upload-percent">0%</strong></div><div style="height:7px;margin-top:8px;border-radius:99px;background:rgba(255,255,255,.08);overflow:hidden"><span class="upload-bar" style="display:block;height:100%;width:0;border-radius:99px;background:linear-gradient(90deg,#229fd0,#54d4ee)"></span></div>';form.insertBefore(progress,form.querySelector('.modal-actions'));form.addEventListener('submit',async e=>{e.preventDefault();const file=input.files?.[0];if(!file)return;const folder=form.querySelector('input[name="folder_id"]')?.value||'';const status=progress.querySelector('.upload-status'),percent=progress.querySelector('.upload-percent'),bar=progress.querySelector('.upload-bar');progress.style.display='block';submit.disabled=true;input.disabled=true;try{const body=new URLSearchParams({filename:file.name,size:String(file.size),mime_type:file.type||'application/octet-stream'});if(folder)body.set('folder_id',folder);let r=await fetch(uploadUrl,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest','Accept':'application/json'},body});let p=await r.json().catch(()=>({}));if(!r.ok)throw Error(p.message||'Upload initialization failed.');const id=p.upload_id,size=Number(p.ch